{"path": "tests/test_users.py", "old_str": "    assert handle_get_user({"id": "99"})[0] == 404", "new_str": "    assert handle_get_user({"id": "99"})[0] == 404


def test_rename_user_ok():
    assert handle_rename_user({"id": "2", "name": "  Renamed User  "}) == (
        200,
        {"id": 2, "name": "Renamed User", "email": "linus@example.com"},
    )


def test_rename_user_visible_through_get_user():
    assert handle_rename_user({"id": "3", "name": "Grace B. Hopper"})[0] == 200
    assert handle_get_user({"id": "3"}) == (
        200,
        {"id": 3, "name": "Grace B. Hopper", "email": "grace@example.com"},
    )


def test_rename_user_accepts_boundary_lengths():
    assert handle_rename_user({"id": "2", "name": "x"}) == (
        200,
        {"id": 2, "name": "x", "email": "linus@example.com"},
    )
    assert handle_rename_user({"id": "2", "name": "y" * 50})[0] == 200


def test_rename_user_invalid_id():
    assert handle_rename_user({"id": "abc", "name": "New Name"}) == (400, {"error": "invalid id"})
    assert handle_rename_user({"name": "New Name"}) == (400, {"error": "invalid id"})
    assert handle_rename_user({"id": 1, "name": "New Name"}) == (400, {"error": "invalid id"})
    assert handle_rename_user({"id": "abc", "name": ""}) == (400, {"error": "invalid id"})


def test_rename_user_invalid_name():
    assert handle_rename_user({"id": "2", "name": ""}) == (400, {"error": "invalid name"})
    assert handle_rename_user({"id": "2", "name": "   "}) == (400, {"error": "invalid name"})
    assert handle_rename_user({"id": "2", "name": "x" * 51}) == (400, {"error": "invalid name"})
    assert handle_rename_user({"id": "2"}) == (400, {"error": "invalid name"})
    assert handle_rename_user({"id": "2", "name": 123}) == (400, {"error": "invalid name"})


def test_rename_user_not_found():
    assert handle_rename_user({"id": "99", "name": "New Name"}) == (404, {"error": "not found"})"}

